  "narrative": "The reference class forecasts show a historically lethal Central Mediterranean route with an unusually high early-2026 pace. Given the 606 deaths by late February and typical spring risk, a 1,000-death threshold by May is highly plausible, yielding a 0.96 posterior probability with a broad yet tight uncertainty band.",
  "justification": {
    "anchor": {
      "probability": 0.68,
      "basis": "Reference class of annual Central Mediterranean fatalities as tracked by IOM Missing Migrants Project; early 2026 pace (606 by Feb) plus historical tolls supports a high probability of hitting 1,000 by May."
    },
    "factor_updates": [
      {
        "factor": "Early-year mortality pace (through February 2026)",
        "direction": "up",
        "magnitude": "strong",
        "rationale": "606 deaths by end-February implies a pace that could sustain into March–April, pushing the total toward 1,000 by May."
      },
      {
        "factor": "High historical baseline and recent annual tolls",
        "direction": "up",
        "magnitude": "moderate",
        "rationale": "Annual tolls around 1,873–2,452 keep the route highly lethal; continuing this pace increases the 1,000-by-May odds."
      },
      {
        "factor": "Weather-related sea conditions and spring crossing risk",
        "direction": "up",
        "magnitude": "moderate",
        "rationale": "Spring conditions typically raise crossing activity and fatalities, supporting the upward path."
      },
      {
        "factor": "IOM funding cuts limiting search-and-rescue and data collection",
        "direction": "up",
        "magnitude": "moderate",
        "rationale": "Funding shortfalls may reduce rescue capacity and data capture, potentially increasing fatalities and undercount risk."
      },
      {
        "factor": "Policy crackdown reducing safe routes and deterring crossings",
        "direction": "up",
        "magnitude": "moderate",
        "rationale": "Hardening border policies can shift crossings to more dangerous routes, elevating fatalities."
      }
    ],
    "synthesis_rationale": "All factors are aligned in the same direction (upward) with strong to moderate influence; the anchor is a high base-rate class. We weight high-probability, forward-looking signals but acknowledge potential dampers (SAR improvements, data revisions). The resulting posterior is 0.96, with a calibrated range 0.90–0.99 to reflect residual uncertainty."
  }
}

