      {
        "factor": "Early-year fatalities pace (through February 2026)",
        "direction": "up",
        "magnitude": "strong",
        "rationale": "606 deaths/missing by late February indicates a momentum that, if sustained into March–April, pushes toward 1,000 by May."
      },
      {
        "factor": "High historical baseline and recent annual tolls",
        "direction": "up",
        "magnitude": "moderate",
        "rationale": "Annual tolls in the 1.8k–2.5k range historically imply the system's capacity to absorb more losses, making 1k by May plausible under current dynamics."
      },
      {
        "factor": "Weather-related sea conditions and spring crossing risk",
        "direction": "up",
        "magnitude": "moderate",
        "rationale": "Seasonal patterns and winter-to-spring weather elevate danger, sustaining high fatality risk in the near term."
